package main

import (
	"fmt"
	"sync"
	"time"
)

// Fungsi yang memakan waktu (simulasi download/query)
func prosesTugas(id int, wg *sync.WaitGroup) {
	// Pastikan Done() dipanggil setelah fungsi ini selesai, bagaimanapun kondisinya
	defer wg.Done()

	fmt.Printf("Goroutine %d: Memulai proses...\n", id)
	// Simulasi delay (misal query database memakan 1 detik)
	time.Sleep(1 * time.Second)
	fmt.Printf("Goroutine %d: Selesai!\n", id)
}

func main() {
	fmt.Println("=== Program Dimulai ===")
	start := time.Now()

	// WaitGroup digunakan untuk menunggu kumpulan goroutine selesai
	var wg sync.WaitGroup

	// Kita akan jalankan 3 proses berat secara BERSAMAAN (Paralel/Konkuren)
	for i := 1; i <= 3; i++ {
		// Tambah 1 antrean tunggu
		wg.Add(1)

		// Jalankan fungsi di latar belakang (Background) dengan kata kunci 'go'
		go prosesTugas(i, &wg)
	}

	fmt.Println("Main: Goroutine sudah ditembak jalan, saya akan menunggu.")

	// Kunci program di sini sampai nilai wg menjadi 0
	wg.Wait()

	fmt.Printf("\n=== Semua selesai dalam %v! ===\n", time.Since(start))
	// Jika kita menjalankannya 1 per 1 tanpa 'go', butuh waktu 3 detik.
	// Dengan 'go', 3 tugas 1 detik selesai hanya dalam ~1 detik!
}
